 public sealed partial class SettingsWindow {
  TextBlock musicActivityText,focusStatusText,autoSceneText,externalTaskText,performanceText,sharedText;ListBox autoRuleList;string sharedSeenHash,sharedSeenPath;Button focusPause,focusResume;bool syncingCompanion;
  void BuildCompanionPages(TabControl tabs){
   var music=SettingsPage(tabs,"音乐");var activity=new StackPanel();TitleText(activity,"现在的音乐联动");musicActivityText=CompanionControls.Text("",13);System.Windows.Automation.AutomationProperties.SetName(musicActivityText,"音乐联动实时状态");activity.Children.Add(musicActivityText);((StackPanel)music.Children[0]).Children.Insert(3,new Border{Child=activity,Padding=new Thickness(14,0,14,12),Margin=new Thickness(0,0,0,12),BorderThickness=new Thickness(1),BorderBrush=PetPalette.Brush(PetPalette.Line),CornerRadius=new CornerRadius(12)});
   BuildFocusPage(tabs);BuildSceneAutomation(SettingsPage(tabs,"场景与维护"));BuildSharedPreferences(SettingsPage(tabs,"场景与维护"));BuildPerformance(SettingsPage(tabs,"场景与维护"));BuildExternalTasks(SettingsPage(tabs,"使用说明"));foreach(var liveText in new[]{musicActivityText,focusStatusText,autoSceneText,externalTaskText,performanceText,sharedText})if(liveText!=null)liveText.Foreground=ink;
  }
  void BuildFocusPage(TabControl tabs){var page=Page(tabs,"专注与休息");TitleText(page,"让琪亚娜陪你专注一会儿");focusStatusText=CompanionControls.Text("",18);page.Children.Add(focusStatusText);var actions=new WrapPanel();actions.Children.Add(Button("开始专注",()=>pet.StartFocus(false),true));actions.Children.Add(Button("开始休息",()=>pet.StartFocus(true),false));focusPause=Button("暂停",pet.PauseFocus,false);focusResume=Button("继续",pet.ResumeFocus,false);actions.Children.Add(focusPause);actions.Children.Add(focusResume);actions.Children.Add(Button("结束并清零本轮",pet.ResetFocus,false));page.Children.Add(actions);AddSlider(page,"专注时长（分钟，下次开始生效）",1,180,pet.Settings.FocusMinutes,1,v=>{pet.Settings.FocusMinutes=v;pet.Save();});AddSlider(page,"休息时长（分钟，下次开始生效）",1,60,pet.Settings.BreakMinutes,1,v=>{pet.Settings.BreakMinutes=v;pet.Save();});Check(page,"专注时暂停自由走动和空闲小动作",pet.Settings.FocusQuiet,v=>{pet.Settings.FocusQuiet=v;pet.Save();});Note(page,"提醒方式");var reminder=new ComboBox{ItemsSource=new[]{"只保留铃铛提示","铃铛＋轻量气泡","铃铛＋气泡与挥手动作"},SelectedIndex=Array.IndexOf(new[]{"badge","bubble","action"},pet.Settings.FocusReminder),Padding=new Thickness(8)};reminder.SelectionChanged+=delegate{pet.Settings.FocusReminder=new[]{"badge","bubble","action"}[Math.Max(0,reminder.SelectedIndex)];pet.Save();};page.Children.Add(reminder);Note(page,"默认 25 分钟专注、5 分钟休息，每一阶段由你主动开始。结束后不会自动进入下一阶段，也不播放声音。锁屏、系统休眠或桌宠退出后暂停；重新打开保留剩余时间，由你点击继续。免打扰或隐藏时延后气泡／动作提醒；不会覆盖 GPT 任务、拖动或睡眠。计时配置可迁移，本轮进度只保留本机。");}
  void BuildSceneAutomation(Panel page){TitleText(page,"自动场景切换");Check(page,"启用自动场景规则",pet.Settings.AutoScenesEnabled,v=>{pet.Settings.AutoScenesEnabled=v;if(v)pet.ResumeAutoScenes();else pet.PauseAutoScenes();pet.Save();});autoSceneText=CompanionControls.Text("");page.Children.Add(autoSceneText);var actions=new WrapPanel();actions.Children.Add(Button("暂停并恢复原设置",delegate{pet.PauseAutoScenes();pet.Save();},false));actions.Children.Add(Button("恢复自动切换",pet.ResumeAutoScenes,false));page.Children.Add(actions);autoRuleList=new ListBox{MinHeight=70,MaxHeight=170,Margin=new Thickness(0,5,0,8)};page.Children.Add(autoRuleList);RefreshAutoRules();var reorder=new WrapPanel();reorder.Children.Add(Button("上移",()=>MoveAutoRule(-1),false));reorder.Children.Add(Button("下移",()=>MoveAutoRule(1),false));reorder.Children.Add(Button("删除规则",delegate{int i=autoRuleList.SelectedIndex;if(i<0)return;pet.Settings.AutoSceneRules=pet.Settings.AutoSceneRules.Where((r,n)=>n!=i).ToArray();pet.Save();RefreshAutoRules();},false));page.Children.Add(reorder);
   var trigger=new ComboBox{ItemsSource=new[]{"正在播放音乐","前台应用","电池供电","指定时段"},SelectedIndex=0,Padding=new Thickness(8)};page.Children.Add(trigger);var process=TextRow(page,"前台应用进程名（例如 Code，不含路径）","");var start=TextRow(page,"时段开始（HH:mm）","09:00");var end=TextRow(page,"时段结束（HH:mm）","18:00");Note(page,"切换到场景");var scene=new ComboBox{ItemsSource=pet.Settings.Scenes.Select(s=>s.Name).ToArray(),SelectedIndex=0,Padding=new Thickness(8)};page.Children.Add(scene);page.Children.Add(Button("添加规则",delegate{try{if(pet.Settings.AutoSceneRules.Length>=20)throw new Exception("最多 20 条规则。");string type=new[]{"music","foreground","battery","time"}[trigger.SelectedIndex],name=Convert.ToString(scene.SelectedItem);if(type=="foreground"&&(string.IsNullOrWhiteSpace(process.Text)||process.Text.IndexOfAny(new[]{'\\','/',':'})>=0))throw new Exception("请填写进程名，例如 Code。");TimeSpan a,b;if(type=="time"&&(!TimeSpan.TryParse(start.Text,out a)||!TimeSpan.TryParse(end.Text,out b)||a.TotalHours<0||a.TotalHours>=24||b.TotalHours<0||b.TotalHours>=24))throw new Exception("请输入 00:00–23:59。");if(type=="music"&&!pet.Settings.Scenes.First(s=>s.Name==name).MusicEnabled)throw new Exception("音乐规则请选择保留音乐栏开启的场景，避免连接被规则自身关闭。");pet.Settings.AutoSceneRules=pet.Settings.AutoSceneRules.Concat(new[]{new AutoSceneRule{Trigger=type,Scene=name,Process=process.Text.Trim(),Start=start.Text,End=end.Text}}).ToArray();pet.Save();RefreshAutoRules();}catch(Exception e){MessageBox.Show(this,e.Message,"规则尚未添加");}},true));Note(page,"列表上方优先；条件持续匹配至少 2 秒后切换。未匹配时恢复进入自动场景前的偏好，自动覆盖不写入永久偏好。你手动应用场景或导入偏好后会暂停自动切换，点击“恢复自动切换”才继续。前台规则只读取进程名，不读取窗口或文档内容。");}
  void RefreshAutoRules(){if(autoRuleList==null)return;int index=autoRuleList.SelectedIndex;autoRuleList.ItemsSource=pet.Settings.AutoSceneRules.Select(r=>(r.Trigger=="music"?"播放音乐":r.Trigger=="battery"?"电池供电":r.Trigger=="foreground"?"前台 "+r.Process:r.Start+"–"+r.End)+" → "+r.Scene).ToArray();autoRuleList.SelectedIndex=Math.Min(Math.Max(0,index),pet.Settings.AutoSceneRules.Length-1);}
  void MoveAutoRule(int delta){int i=autoRuleList.SelectedIndex,j=i+delta;if(i<0||j<0||j>=pet.Settings.AutoSceneRules.Length)return;var rules=pet.Settings.AutoSceneRules;var item=rules[i];rules[i]=rules[j];rules[j]=item;pet.Save();RefreshAutoRules();autoRuleList.SelectedIndex=j;}
  void BuildSharedPreferences(Panel page){TitleText(page,"共享偏好快照");sharedText=CompanionControls.Text("");page.Children.Add(sharedText);page.Children.Add(Button("选择共享文件位置…",delegate{var picker=new SaveFileDialog{Title="绑定共享偏好文件（此步骤不发布）",Filter="桌宠共享快照 (*.json)|*.json",FileName="Kiana-shared-preferences.json",OverwritePrompt=false};if(picker.ShowDialog(this)!=true)return;string file=Path.GetFullPath(picker.FileName);if(file.StartsWith(Path.GetFullPath(Store.Root).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)){MessageBox.Show(this,"请选择运行数据目录以外的共享文件夹。","选择共享位置");return;}pet.Settings.SharedPreferenceFile=file;pet.Save();sharedSeenHash=sharedSeenPath=null;sharedText.Text="已绑定："+file+"\n点击检查读取另一台电脑的快照，或首次发布本机偏好。";},false));page.Children.Add(Button("检查差异并选择应用…",ReviewShared,true));page.Children.Add(Button("发布本机通用偏好",PublishShared,false));page.Children.Add(Button("解除共享文件绑定",delegate{pet.Settings.SharedPreferenceFile="";pet.Save();sharedSeenHash=sharedSeenPath=null;sharedText.Text="尚未绑定共享文件";},false));sharedText.Text=pet.Settings.SharedPreferenceFile.Length==0?"尚未绑定共享文件":"已绑定："+pet.Settings.SharedPreferenceFile+"\n等待手动检查。";Note(page,"两台电脑选择同一份共享 JSON 文件，可放在你已有的同步盘或共享目录。桌宠负责检查、差异预览与原子发布，文件跨机传输由该目录负责；不会登录云盘或自动提交到 GitHub。每项通用偏好可单独勾选，应用前备份；发布前若发现文件已被另一台修改，会拒绝覆盖并要求重新检查。路径、位置、联动方式、性能预设和本机自动规则不共享。离线同步盘产生的冲突副本需手动选定一份后重新检查。");}
  string SharedPath(){if(string.IsNullOrWhiteSpace(pet.Settings.SharedPreferenceFile))throw new Exception("请先选择共享文件位置。");return pet.Settings.SharedPreferenceFile;}
  async void ReviewShared(){try{string path=SharedPath();IsEnabled=false;var read=await System.Threading.Tasks.Task.Run(()=>SharedPreferences.Read(path));if(!IsLoaded)return;IsEnabled=true;sharedSeenPath=path;sharedSeenHash=read==null?null:read.Hash;if(read==null){sharedText.Text="还没有快照，可点击发布本机通用偏好。";return;}sharedText.Text="快照来自 "+read.Snapshot.Device+" · "+read.Snapshot.CreatedAt.ToLocalTime().ToString("MM-dd HH:mm")+"\n版本 "+read.Info.Version+" · 修订 "+read.Snapshot.Revision.Substring(0,Math.Min(8,read.Snapshot.Revision.Length));var review=new SharedPreferenceReviewWindow(pet,path,read){Owner=this};if(review.ShowDialog()==true){pet.RefreshSettingsAfterShared();}}catch(Exception e){if(IsLoaded)MessageBox.Show(this,e.Message,"共享偏好检查失败");}finally{if(IsLoaded)IsEnabled=true;}}
  async void PublishShared(){try{string path=SharedPath();pet.Save();var preferences=pet.PersistentPreferences();string expected=sharedSeenHash;IsEnabled=false;var result=await System.Threading.Tasks.Task.Run(()=>SharedPreferences.Publish(path,preferences,expected));if(!IsLoaded)return;sharedSeenHash=result.Hash;sharedSeenPath=path;sharedText.Text="已发布本机通用偏好 · "+result.Snapshot.CreatedAt.ToLocalTime().ToString("HH:mm:ss")+"\n另一台电脑可检查并应用。";}catch(Exception e){if(IsLoaded)MessageBox.Show(this,e.Message,"尚未发布");}finally{if(IsLoaded)IsEnabled=true;}}
  void BuildPerformance(Panel page){TitleText(page,"性能与省电");var profile=new ComboBox{ItemsSource=new[]{"保留原有策略","安静：降低刷新与后台开销","均衡：正常动画与后台节流","流畅：互动时提高刷新"},SelectedIndex=Array.IndexOf(CompanionOptions.Profiles,pet.Settings.PerformanceProfile),Padding=new Thickness(8)};profile.SelectionChanged+=delegate{pet.Settings.PerformanceProfile=CompanionOptions.Profiles[Math.Max(0,profile.SelectedIndex)];pet.Save();};page.Children.Add(profile);Check(page,"电池供电时临时使用安静策略",pet.Settings.BatterySaving,v=>{pet.Settings.BatterySaving=v;pet.Save();});performanceText=CompanionControls.Text("");page.Children.Add(performanceText);Note(page,"策略只影响桌宠自身的动画定时器与音乐轮询，不重启或调整播放器和 GPT。歌词播放时保持正常进度采样；非原有策略在隐藏时降低音乐轮询频率，锁屏时进一步降低。GPT 已连接时保留原有两秒续期，断连继续退避重试。减少动态效果独立生效。CPU 与内存为此桌宠进程的实测值，并不代表整机占用；刷新间隔也不等于素材实际帧率。");}
  void BuildExternalTasks(Panel page){Check(page,"启用外部脚本任务接收",pet.Settings.ExternalNoticesEnabled,v=>{pet.Settings.ExternalNoticesEnabled=v;pet.Save();});externalTaskText=CompanionControls.Text("");page.Children.Add(externalTaskText);page.Children.Add(Button("复制发送通知示例",delegate{string exe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"KianaDesktopPet.exe");Clipboard.SetText("& '"+exe.Replace("'","''")+"' --task-notice --state-dir '"+Store.Root.Replace("'","''")+"' --source '训练脚本' --task-id 'run-001' --status 'succeeded' --title '训练已完成'");pet.Say("示例已复制，可粘贴到 PowerShell。",3);},false));Note(page,"脚本通过 --task-notice 或 tools/Send-TaskNotice.ps1 发送 running / succeeded / failed / waiting。相同来源和任务编号更新同一条通知，事件去重并拒绝旧事件覆盖新状态；可选输出路径只在点击时用资源管理器定位。不执行通知中的命令或链接，不监听网络端口。也可用 tools/Invoke-TaskWithNotice.ps1 包裹你指定的训练、导出或下载命令，自动发送开始／成功／失败，保留退出码；现有程序不会被自动修改。");}
  void UpdateCompanionStatus(){if(syncingCompanion)return;syncingCompanion=true;try{if(musicActivityText!=null)musicActivityText.Text=pet.MusicActivityStatus.ToString();if(focusStatusText!=null){focusStatusText.Text=pet.FocusStatus;focusPause.IsEnabled=pet.FocusRunning;focusResume.IsEnabled=pet.FocusCanResume;}if(autoSceneText!=null)autoSceneText.Text=pet.AutoSceneStatus;if(externalTaskText!=null)externalTaskText.Text=pet.ExternalTaskStatus;if(performanceText!=null&&ActiveCategory=="场景与维护")performanceText.Text=pet.PerformanceStatus;}finally{syncingCompanion=false;}}
 }
 public sealed partial class PetWindow {
  public bool FocusRunning{get{return focusClock.Session.Running;}}
  public bool FocusCanResume{get{return !focusClock.Session.Running&&focusClock.Session.Remaining>0&&(focusClock.Session.Phase=="focus"||focusClock.Session.Phase=="break");}}
  public void RefreshSettingsAfterShared(){RefreshSettingsWindow();}
 }
